//! Independent NumPy CART/boosting, sklearn SVR, SciPy exact GP and linear
//! references, regenerated by tool/refs/stats/ml_regression.py (never MATLAB).
use matrust::{Array, Engine};
use serde::Deserialize;
use std::collections::BTreeMap;
#[derive(Deserialize)]
struct Case {
    name: String,
    code: String,
    values: BTreeMap<String, Vec<f64>>,
    tolerance: f64,
}
fn run(e: &mut Engine, code: &str) {
    e.execute(code)
        .unwrap_or_else(|err| panic!("{code}: {err}"));
}
fn numbers(e: &Engine, name: &str) -> Vec<f64> {
    match &e.workspace()[name] {
        Array::Numeric(x) => x.data().to_vec(),
        a => panic!("{name}: unexpected {}", a.class()),
    }
}
fn reference(prefix: &str) {
    let cases: Vec<Case> =
        serde_json::from_str(include_str!("fixtures/ml_regression.json")).unwrap();
    let mut checked = 0;
    for c in cases.into_iter().filter(|c| c.name.starts_with(prefix)) {
        let mut e = Engine::default();
        run(&mut e, &c.code);
        for (name, expected) in c.values {
            let got = numbers(&e, &name);
            assert_eq!(got.len(), expected.len(), "{} {name}", c.name);
            for (i, (got, want)) in got.iter().zip(expected).enumerate() {
                assert!(
                    (got - want).abs() <= c.tolerance,
                    "{} {name}[{i}]: got {got:.16}, expected {want:.16}",
                    c.name
                );
            }
        }
        checked += 1;
    }
    assert!(checked > 0);
}
