    let mut e = Engine::default();
    run(
        &mut e,
        "x=(0:9)';y=[0;2;1;4;3;6;5;8;7;10];rng(3);a=fitrsvm(x,y,'KernelFunction','gaussian','KernelScale','auto');rng(3);b=fitrsvm(x,y,'KernelFunction','gaussian','KernelScale','auto');assert(isequal(predict(a,x),predict(b,x)));assert(isequal(a.Alpha,b.Alpha));assert(abs(sum(a.Alpha))<1e-8);assert(sum(double(a.IsSupportVector))==size(a.SupportVectors,1));m=fitrsvm([1;1;1],[2;2;2]);assert(abs(predict(m,1)-2)<1e-10);r=fitrtree([0;1],[3;3]);assert(resubLoss(r)==0);",
    );
