fn invalid_inputs_and_options() {
    for code in [
        "fitrtree([0;1],[1;2;3])",
        "fitrsvm([0;1],[NaN;NaN])",
        "fitrgp([0;Inf],[1;2])",
        "fitrlinear([0;1],[1;2],'NoSuchOption',1)",
        "fitrtree([0;1],[1;2],'PredictorSelection','curvature')",
        "fitrtree([0;1],[1;2],'MinLeafSize',0)",
        "fitrtree([0;1],[1;2],'MinParentSize',1)",
        "fitrsvm([0;1],[1;2],'BoxConstraint',0)",
        "fitrsvm([0;1],[1;2],'Epsilon',-1)",
        "fitrsvm([0;1],[1;2],'KernelFunction','unknown')",
        "fitrsvm([0;1],[1;2],'KernelScale',0)",
        "fitrgp([0;1],[1;2],'FitMethod','sr')",
        "fitrgp([0;1],[1;2],'Basis','quadratic')",
        "fitrgp([0;1],[1;2],'KernelParameters',[1;2;3])",
        "fitrensemble([0;1],[1;2],'Method','unknown')",
        "fitrensemble([0;1],[1;2],'NumLearningCycles',0)",
        "fitrlinear([0;1],[1;2],'Lambda',-1)",
        "m=fitrtree([0;1],[1;2]); predict(m,[0 1])",
        "m=fitrtree([0;1],[1;2]); crossval(m,'KFold',3)",
        "m=fitrtree([0;1],[1;2]); kfoldLoss(m)",
        "m=fitrensemble([0;1],[1;2]); oobLoss(m)",
        "m=fitrtree([0;1],[1;2]); crossval(m,'CVPartition',3)",
        "t=table([0;1],[1;2],'VariableNames',{'x','y'}); fitrtree(t,'y~x^2')",
    ] {
        let err = Engine::default().execute(code).expect_err(code);
        assert!(!err.is_empty());
    }
}

#[test]
fn regression_help_examples_run() {
    for name in [
        "fitrtree",
        "fitrsvm",
        "fitrgp",
        "fitrensemble",
        "fitrlinear",
        "templateTree",
        "cvpartition",
        "test",
        "training",
        "loss",
        "prune",
        "predictorImportance",
        "oobLoss",
    ] {
        let page = matrust::help::page(name).unwrap_or_else(|| panic!("missing help for {name}"));
        let mut count = 0;
        for line in page.lines() {
            if let Some(code) = line.strip_prefix("Example: ") {
                run(&mut Engine::default(), code);
                count += 1;
            }
        }
        assert!(count > 0, "{name}: missing help examples");
        assert!(matrust::session::FUNCTIONS.contains(&name));
    }
}

#[test]
fn shared_partition_refits_stratified_folds_for_both_engines() {
    let mut e = Engine::default();
    run(
        &mut e,
        "x=(0:11)';g=[ones(6,1);2*ones(6,1)];y=[1;2;1;3;4;3;5;6;5;7;8;7];rng(17);cp=cvpartition(g,'KFold',3);c=fitctree(x,g,'MinParentSize',2);ccv=crossval(c,'CVPartition',cp);assert(isfinite(kfoldLoss(ccv)));assert(numel(kfoldPredict(ccv))==12);",
    );
    for fit in [
        "fitrtree",
        "fitrsvm",
        "fitrgp",
        "fitrensemble",
        "fitrlinear",
    ] {
        let opts = if fit == "fitrensemble" {
            ",'NumLearningCycles',3"
        } else {
            ""
        };
        run(
            &mut e,
            &format!(
                "m={fit}(x,y{opts});cv=crossval(m,'CVPartition',cp);p=kfoldPredict(cv);for k=1:3;tr=training(cp,k);te=test(cp,k);a={fit}(x(tr,:),y(tr){opts});assert(max(abs(p(te)-predict(a,x(te,:))))<1e-8);end;assert(abs(kfoldLoss(cv)-mean((p-y).^2))<1e-10);"
            ),
        );
    }
    run(
        &mut e,
        "m=fitrlinear(x,y);cp=cvpartition(12,'Leaveout');a=crossval(m,'CVPartition',cp);b=crossval(m,'Leaveout','on');assert(isequal(kfoldPredict(a),kfoldPredict(b)));cp=cvpartition(12,'Resubstitution');a=crossval(m,'CVPartition',cp);assert(isequal(kfoldPredict(a),predict(m,x)));assert(abs(kfoldLoss(a)-resubLoss(m))<1e-12);rng(8);cp=cvpartition(g,'Holdout',.25);a=crossval(m,'CVPartition',cp);p=kfoldPredict(a);assert(isequal(isnan(p),training(cp)));assert(isfinite(kfoldLoss(a)));",
    );
}

#[test]
fn shared_templates_and_metrics_route_by_model_class() {
    let mut e = Engine::default();
    run(
        &mut e,
        "x=(0:11)';g=[ones(6,1);2*ones(6,1)];y=x.^2;t=templateTree('MaxNumSplits',1,'MinParentSize',2,'MinLeafSize',1,'PredictorSelection','allsplits');r=fitrensemble(x,y,'Learners',t,'NumLearningCycles',3);c=fitcensemble(x,g,'Learners',t,'Method','Bag','NumLearningCycles',8);assert(abs(loss(r,x,y)-resubLoss(r))<1e-10);assert(loss(c,x,g)==resubLoss(c));assert(predictorImportance(r)>0);assert(predictorImportance(c)>0);assert(isfinite(oobLoss(c)));rng(4);r=fitrensemble(x,y,'Learners',t,'Method','Bag','NumLearningCycles',8);o=oobLoss(r);assert(numel(o)==8);assert(abs(o(8)-oobLoss(r,'Mode','ensemble'))<1e-12);t=templateTree('MaxNumSplits',0);r=fitrensemble(x,y,'Learners',t,'NumLearningCycles',2);c=fitcecoc(x,g,'Learners',t);assert(max(abs(predict(r,x)-mean(y)))<1e-10);assert(all(predictorImportance(r)==0));assert(numel(predict(c,x))==12);",
    );
}

#[test]
fn shared_names_have_single_registry_and_help_entries() {
    for name in [
        "cvpartition",
        "training",
        "test",
        "templateTree",
        "loss",
        "oobLoss",
        "predictorImportance",
    ] {
        assert_eq!(
            matrust::session::FUNCTIONS
                .iter()
                .filter(|&&n| n == name)
                .count(),
            1,
            "{name}"
        );
        let heading = format!("## {name}");
        assert_eq!(
            include_str!("../assets/help/functions.md")
                .lines()
                .filter(|line| *line == heading)
                .count(),
            1,
            "{name}"
        );
    }
}

#[test]
fn shared_partition_and_template_validation() {
    for code in [
        "m=fitrtree([0;1],[1;2]);cp=cvpartition(3,'Leaveout');crossval(m,'CVPartition',cp)",
        "m=fitrtree([0;1],[1;2]);cp=cvpartition(2,'Holdout',.99);crossval(m,'CVPartition',cp)",
        "m=fitrtree([0;1],[1;2]);crossval(m,'Holdout',.99)",
        "m=fitrtree(1,2);crossval(m,'Leaveout','on')",
        "m=fitrtree([0;1],[1;2]);crossval(m,'CVPartition',templateTree())",
        "m=fitrtree([0;1],[1;2]);crossval(m,'KFold',2,'Holdout',.5)",
        "m=fitrtree(zeros(1001,1),ones(1001,1));cp=cvpartition(1001,'Leaveout');crossval(m,'CVPartition',cp)",
        "fitrensemble([0;1],[1;2],'Learners',templateSVM())",
        "templateTree('PredictorSelection','curvature')",
        "templateTree('MaxNumSplits',-.5)",
        "templateTree('MaxNumSplits',1.5)",
    ] {
        assert!(Engine::default().execute(code).is_err(), "{code}");
    }
}
#[test]
fn fitrgp_converges_from_far_start() {
    // docs/tasks/2026-11-12-fitrgp-gpdiag.m: the Regression Learner start
    // (Sigma 0.1, KernelParameters [10 100]) on full data and 5 folds, seeds
    // 0..3. Every fit must return a model; references are SciPy BFGS on the
    // same profiled likelihood (tool/refs/stats/ml_regression.py).
    let cases: Vec<Case> =
        serde_json::from_str(include_str!("fixtures/ml_regression.json")).unwrap();
    for (nonlinear, basis) in [(0, "constant"), (1, "linear")] {
        let reference = cases
            .iter()
            .find(|c| c.name == format!("gpfar_{basis}"))
            .unwrap();
        let mut e = Engine::default();
        run(
            &mut e,
            &format!(
                "nonlinear={nonlinear}; state=1121; a=zeros(200,1); b=a; y=a;
for i=1:200
  state=mod(state*1664525+1013904223,4294967296); x1=(state/4294967296-0.5)*4;
  state=mod(state*1664525+1013904223,4294967296); x2=(state/4294967296-0.5)*4;
  state=mod(state*1664525+1013904223,4294967296); noise=(state/4294967296-0.5)*0.05;
  if nonlinear, x=-3+6*(i-1)/199; a(i)=x; y(i)=sin(x)+noise; else, a(i)=x1; b(i)=x2; y(i)=3*x1-2*x2+0.5*x1*x2+noise; end
end
if nonlinear, X=a; else, X=[a b]; end
{}
S=zeros(4,6);
for s=0:3
  rng(s); c=cvpartition(200,'KFold',5);
  for k=0:5
    if k==0, idx=true(200,1); else, idx=training(c,k); end
    f=fitrgp(X(idx,:),y(idx),'KernelFunction','squaredexponential','Sigma',0.1,'KernelParameters',[10 100],'BasisFunction','{basis}');
    S(s+1,k+1)=f.Sigma;
  end
end",
                reference.code
            ),
        );
        for (name, expected) in &reference.values {
            let got = numbers(&e, name);
            assert_eq!(got.len(), expected.len(), "{basis} {name}");
            for (got, want) in got.iter().zip(expected) {
                assert!(
                    (got - want).abs() <= reference.tolerance * want.abs(),
                    "{basis} {name}: got {got:.16}, expected {want:.16}"
                );
            }
        }
        let full = numbers(&e, "sigma")[0];
        for (i, s) in numbers(&e, "S").iter().enumerate() {
            assert!(
                (s - full).abs() <= 0.15 * full,
                "{basis} fit {i}: Sigma {s} vs full-data {full}"
            );
        }
    }
}

#[test]
fn fitrgp_rational_quadratic_converges() {
    // All 18 fits of docs/tasks/2026-11-12-fitrgp-rq.m, without catching errors.
    // A boundary shape is unidentifiable, so compare likelihoods rather than
    // requiring an optimizer path or extreme alpha to match across platforms.
    let cases: Vec<Case> =
        serde_json::from_str(include_str!("fixtures/ml_regression.json")).unwrap();
    let reference = cases.iter().find(|c| c.name == "gprq_far").unwrap();
    let mut e = Engine::default();
    run(&mut e, "state=1121; a=zeros(60,1); b=a; y=a;
for i=1:60
  state=mod(state*1664525+1013904223,4294967296); x1=(state/4294967296-0.5)*4;
  state=mod(state*1664525+1013904223,4294967296); x2=(state/4294967296-0.5)*4;
  state=mod(state*1664525+1013904223,4294967296); noise=(state/4294967296-0.5)*0.05;
  a(i)=x1; b(i)=x2; y(i)=3*x1-2*x2+0.5*x1*x2+noise;
end
X=[a b]; LL=zeros(6,3); fits=0;
for s=0:5
  rng(s); c=cvpartition(60,'KFold',2);
  for k=0:2
    if k==0, idx=true(60,1); else, idx=training(c,k); end
    m=fitrgp(X(idx,:),y(idx),'KernelFunction','rationalquadratic','Sigma',0.1,'KernelParameters',[10 1 100],'BasisFunction','constant');
    LL(s+1,k+1)=m.LogLikelihood; fits=fits+1;
  end
end
assert(fits==18); assert(all(isfinite(LL(:))));");
    let expected = reference.values["ll"][0];
    for likelihood in &numbers(&e, "LL")[..6] {
        assert!(
            *likelihood >= expected - 1e-6 * expected.abs().max(1.),
            "full-data log likelihood {likelihood:.16} below SciPy {expected:.16}"
        );
    }
}
